function finishLegacyClip(){const rec=G.clipRecording;if(!rec)return;G.clipRecording=null;G.run=false;const frames=rec.frames;if(frames.length<2){refreshGym();gMessage('Clip too short. Record while moving a joint.');return}const first=frames[0];const joints=first.a.map((_,i)=>i).filter(i=>(!rec.moved||rec.moved.has(i))&&Math.max(...frames.map(f=>f.a[i]))-Math.min(...frames.map(f=>f.a[i]))>.035);if(!joints.length){refreshGym();gMessage('No joint movement detected. Drag a finger while recording.');return}const start=frames[0].t;const clip={name:rec.name,joints,frames:frames.map(f=>({t:f.t-start,a:joints.map(i=>f.a[i])}))};const slot=Number.isInteger(rec.slot)?rec.slot:G.clips.findIndex(c=>c.name.toLowerCase()===rec.name.toLowerCase());if(slot>=0&&slot<G.clips.length)G.clips[slot]=clip;else G.clips.push(clip);G.buffer=[];G.activeClip=null;G.heldClipTargets={};$('clipName').value='';refreshGym();persistGym();gMessage(`Saved “${rec.name}” to key ${slot>=0&&slot<G.clips.length?slot+1:G.clips.length}. Only ${joints.length} moving joints will play.`)}
