function normalizeState(policy,x){return x.map((v,i)=>clamp((v-policy.mean[i])/policy.scale[i],-8,8))}
function neuralForward(policy,x,history=[],record=true){const state=normalizeState(policy,x);if(record){history.push(state);if(history.length>(policy.architecture.type==='feedforward'?1:policy.architecture.context))history.shift()}return RobotTransformer.forward(policy,record?history:[...history.slice(0,-1),state])}
