function recordedPose(f){if(f.b?.length===model.boxes.length)return f.b;const poses=new Map(model.boxes.map(b=>[b.id,{...b}])),done=new Set(model.boxes.filter(b=>b.anchored).map(b=>b.id));if(!done.size&&model.boxes.length)done.add(model.boxes[0].id);for(let pass=0;pass<model.boxes.length;pass++)model.pins.forEach((j,i)=>{const a=poses.get(j.a),b=poses.get(j.b),ref=box(j.b).angle-box(j.a).angle;if(done.has(j.a)&&!done.has(j.b)){b.angle=a.angle+ref+f.a[i];const p=E.anchor(a,j.pa),off=E.rotate({x:j.pb.x*b.w,y:j.pb.y*b.h},b.angle);b.x=p.x-off.x;b.y=p.y-off.y;done.add(j.b)}else if(done.has(j.b)&&!done.has(j.a)){a.angle=b.angle-ref-f.a[i];const p=E.anchor(b,j.pb),off=E.rotate({x:j.pa.x*a.w,y:j.pa.y*a.h},a.angle);a.x=p.x-off.x;a.y=p.y-off.y;done.add(j.a)}});return model.boxes.map(b=>{const p=poses.get(b.id);return[p.x,p.y,p.angle]})}
